/**
 * "Explain this order" — plain-English account of why an order intent looks the way it does, built ONLY from
 * stored data: intent meta (rationale, alternatives), the policy verdict and the hash-chained audit events.
 * Nothing here is generated by an LLM, so it cannot be talked into a different story.
 */
import { getAuditTrail, verifyAuditChain, type AuditEvent } from "../audit/chain.js";
import { getIntent, type OrderIntent } from "../orders/store.js";

/** Every rule the policy engine evaluates, with a plain-English meaning. */
export const POLICY_RULES: Record<string, string> = {
  mandate_expired: "the purchasing mandate is still valid",
  allergen_restrictions: "allergen / lactose restrictions are respected",
  over_spend: "the total is within the maximum order value",
  over_quantity: "the quantity is within the maximum allowed",
  late_delivery: "delivery arrives on or before the date needed",
  unknown_reliability: "the supplier's delivery reliability is known",
  substitution: "no substitution without sign-off",
  partial_fulfil: "the full quantity can be delivered",
  category_not_allowed: "the product category is allowed by the mandate",
  brand_not_allowed: "the product brand is allowed by the mandate",
  over_unit_price: "the unit price is within the requested cap",
  over_daily_spend: "cumulative daily spend is within the limit",
  over_weekly_spend: "cumulative weekly spend is within the limit",
  over_monthly_spend: "cumulative monthly spend is within the limit",
  over_order_velocity: "daily order count is within the limit",
  order_splitting_suspected: "no order-splitting pattern detected",
  price_change_on_revalidate: "live price at commit stayed within drift tolerance",
};

export type ExplainTimelineItem = { at: string; actor: "agent" | "human" | "system"; event: string; why: string };

export type OrderExplanation = {
  intentId: string;
  status: string;
  summary: string;
  timeline: ExplainTimelineItem[];
  decision: {
    by: "agent" | "human";
    outcome: string;
    rulesChecked: Array<{ rule: string; meaning: string; result: "passed" | "failed" | "overridden" }>;
    rulesFailed: string[];
    rulesOverridden: string[];
    reasons: string[];
  };
  offers: {
    consideredCount: number;
    chosen: { productId: string; productName: string; totalPrice: number; whyChosen: string[] } | null;
    alternatives: Array<{ productId: string; productName: string; totalPrice: number; deltaEur: number; canFulfil: boolean; isSubstitution: boolean; whyNotChosen: string }>;
  };
  facts: Array<{
    productId: string;
    productName: string;
    unitPrice: number;
    totalPrice: number;
    packs: number;
    availableDate: string | null;
    availableQuantity: number | null;
    deliveryReliability: number | null;
    signedClaims: number;
    claimVerification: { status: "revalidated_before_commit" | "signed_awaiting_recheck" | "failed_recheck" | "unsigned"; detail: string };
  }>;
  audit: { runId: string; events: number; chainValid: boolean };
};

const eur = (n: number) => `€${Number(n).toFixed(2)}`;
const humanRule = (r: string) => POLICY_RULES[r] ?? r.replace(/_/g, " ");
const failedPhrase = (r: string) =>
  ({
    mandate_expired: "the purchasing mandate has expired",
    allergen_restrictions: "an allergen or lactose restriction was not met",
    over_spend: "the total is above the spending limit",
    over_quantity: "the quantity is above the allowed maximum",
    late_delivery: "delivery would arrive after the date needed",
    unknown_reliability: "the supplier's delivery reliability is unknown",
    substitution: "it is a substitute product",
    partial_fulfil: "Valio cannot deliver the full quantity",
    category_not_allowed: "the product category is outside the allowed mandate categories",
    brand_not_allowed: "the product brand is outside the allowed mandate brands",
    over_unit_price: "the unit price exceeds the requested maximum",
    over_daily_spend: "the order exceeds the daily spending cap",
    over_weekly_spend: "the order exceeds the weekly spending cap",
    over_monthly_spend: "the order exceeds the monthly spending cap",
    over_order_velocity: "the daily order velocity limit was exceeded",
    order_splitting_suspected: "multiple orders near the per-order limit suggest order splitting",
    price_change_on_revalidate: "the live price rose beyond tolerance at commit time",
  })[r] ?? r.replace(/_/g, " ");

type P = Record<string, any>;

function bound(events: AuditEvent[], intentId: string): AuditEvent[] {
  const tagged = events.filter((e) => (e.payload as P)?.intentId === intentId);
  const created = events.find((e) => e.type === "intent_created" && (e.payload as P)?.intentId === intentId);
  // Untagged run-level events (need, offers, policy) belong to the intent proposed right after them.
  const limit = created ? created.id + 1 : Number.MAX_SAFE_INTEGER;
  const lastOf = (type: string) => [...events].reverse().find((e) => e.type === type && e.id <= limit);
  const pre = ["need_validated", "offers_built", "policy_evaluated"].map(lastOf).filter(Boolean) as AuditEvent[];
  const seen = new Set<number>();
  return [...pre, ...tagged].filter((e) => (seen.has(e.id) ? false : (seen.add(e.id), true))).sort((a, b) => a.id - b.id);
}

function timelineItem(e: AuditEvent, intent: OrderIntent): ExplainTimelineItem | null {
  const p = e.payload as P;
  const at = e.createdAt;
  switch (e.type) {
    case "need_validated":
      return { at, actor: "agent", event: `Request received: ${p.quantity} ${p.unit} of ${p.productIntent} needed by ${p.neededBy}`, why: "Every purchase starts as a structured need so it can be checked against the mandate." };
    case "offers_built":
      return { at, actor: "agent", event: `Compared ${p.count} Valio offer(s) using live price and stock`, why: "Offers are ranked on price, delivery date, reliability and fit to the request." };
    case "intent_created":
      return { at, actor: "agent", event: `Proposed ${p.productName} for ${eur(p.totalPrice)}`, why: (p.why ?? []).slice(0, 3).join(" ") || "It was the best-ranked offer that fits the need." };
    case "policy_evaluated":
      return {
        at,
        actor: "system",
        event: p.decision === "auto_commit" ? "Mandate check passed" : p.decision === "blocked" ? "Mandate check blocked the order" : "Mandate check requires a human decision",
        why: (p.reasons ?? []).join(" ") || "Checked against the buyer's purchasing mandate.",
      };
    case "human_approved":
      return { at, actor: "human", event: p.mandateOverride ? "A person approved the order and overrode the mandate" : "A person approved the order", why: p.mandateOverride ? `They acknowledged: ${(p.acknowledgedRules ?? []).map(failedPhrase).join("; ")}.` : "The order was within the rules but approval was requested." };
    case "human_rejected":
      return { at, actor: "human", event: "A person rejected the order", why: p.reason ? String(p.reason) : "No reason given." };
    case "approval_blocked_no_override":
      return { at, actor: "system", event: "Approval was refused", why: "The order breaks the mandate and no explicit override was given." };
    case "approval_blocked_incomplete_ack":
      return { at, actor: "system", event: "Approval was refused", why: "The override did not acknowledge every rule that failed." };
    case "approval_rejected_snapshot_mismatch":
      return { at, actor: "system", event: "Approval invalidated", why: "The basket changed after it was shown, so the approval no longer applied." };
    case "revalidating":
      return { at, actor: "system", event: "Re-checked price and availability with Valio", why: "Prices and stock move, so they are confirmed again right before ordering." };
    case "stale_offer":
      return { at, actor: "system", event: `Order stopped: ${String(p.reason).replace(/_/g, " ")} changed`, why: "The quote was no longer valid, so nothing was ordered." };
    case "intent_expired":
      return { at, actor: "system", event: "Proposal expired", why: "Unapproved proposals lapse after one hour so old prices are never used." };
    case "intent_superseded":
      return { at, actor: "system", event: "Replaced by a newer proposal", why: "A newer proposal for the same need took its place." };
    case "committed":
      return { at, actor: "agent", event: `Order ${p.orderId} placed for ${eur(p.totalPrice)}`, why: "All checks passed and the quote was still valid." };
    default:
      return null;
  }
}

export function explainOrder(intentId: string, customerId: string): OrderExplanation | null {
  const intent = getIntent(intentId, customerId);
  if (!intent) return null;
  const events = getAuditTrail(intent.runId, customerId);
  const mine = bound(events, intent.id);
  const approved = mine.find((e) => e.type === "human_approved");
  const rejected = mine.find((e) => e.type === "human_rejected");
  const stale = mine.find((e) => e.type === "stale_offer");
  const revalidated = mine.some((e) => e.type === "revalidating") && !stale && intent.status === "committed";

  const failing = intent.policy.failingRules ?? [];
  const overridden = approved && (approved.payload as P).mandateOverride ? ((approved.payload as P).acknowledgedRules as string[] | undefined) ?? failing : [];
  const decidedByHuman = Boolean(approved || rejected);

  const timeline = mine.map((e) => timelineItem(e, intent)).filter(Boolean) as ExplainTimelineItem[];

  const rulesChecked = Object.entries(POLICY_RULES).map(([rule, meaning]) => ({
    rule,
    meaning,
    result: (overridden.includes(rule) ? "overridden" : failing.includes(rule) ? "failed" : "passed") as "passed" | "failed" | "overridden",
  }));

  const line = intent.basket[0];
  const meta = intent.meta;
  const chosenWhy = meta?.rationale ?? [];

  const claimStatus = (l: OrderIntent["basket"][number]): OrderExplanation["facts"][number]["claimVerification"] => {
    if (l.claimIds.length === 0) return { status: "unsigned", detail: "No signed Valio claim is attached to this line." };
    if (stale) return { status: "failed_recheck", detail: `The live re-check before ordering failed (${String((stale.payload as P).reason).replace(/_/g, " ")}); the order was stopped.` };
    if (revalidated) return { status: "revalidated_before_commit", detail: "Signed price and availability claims were attached, and Valio's live price and stock were re-confirmed before the order was placed." };
    return { status: "signed_awaiting_recheck", detail: "Price and availability were signed by the gateway when proposed. They are re-confirmed with Valio just before any order is placed." };
  };

  const outcomeByStatus: Record<string, string> = {
    committed: "Order placed",
    approved: "Approved, waiting to be placed",
    pending_approval: "Waiting for a person to approve",
    auto_eligible: "Within the mandate, can be placed automatically",
    blocked: "Blocked by the mandate",
    rejected: "Rejected by a person",
    expired: "Expired before approval",
    stale_invalidated: "Stopped because the quote went stale",
    superseded: "Replaced by a newer proposal",
  };
  const outcome = outcomeByStatus[intent.status] ?? intent.status.replace(/_/g, " ");

  const failedText = failing.map(failedPhrase);
  const by: "agent" | "human" = decidedByHuman || intent.policy.decision === "pending_approval" ? "human" : "agent";
  const parts: string[] = [];
  parts.push(`The agent looked for ${intent.need.quantity} ${intent.need.unit} of ${intent.need.productIntent} needed by ${intent.need.neededBy}${meta ? ` and compared ${meta.consideredOffers} offer(s)` : ""}.`);
  if (line) parts.push(`It chose ${line.productName} at ${eur(intent.totalPrice)}${chosenWhy[0] ? `, because ${chosenWhy[0].charAt(0).toLowerCase()}${chosenWhy[0].slice(1).replace(/\.$/, "")}` : ""}.`);
  if (intent.policy.decision === "auto_commit") parts.push("Every rule in the purchasing mandate was met, so the agent was allowed to buy without asking.");
  else if (intent.policy.decision === "blocked") parts.push(`The mandate blocked this order: ${failedText.join("; ") || "policy"}.`);
  else parts.push(`A person had to decide because ${failedText.join("; ") || "the mandate requires approval"}.`);
  if (approved) parts.push(overridden.length ? "A person approved it and knowingly overrode the failed rule(s)." : "A person approved it.");
  if (rejected) parts.push("A person rejected it.");
  if (intent.status === "committed") parts.push(`The order was placed${intent.committedOrderId ? ` (${intent.committedOrderId})` : ""} after price and stock were re-checked.`);
  else if (stale) parts.push("It was stopped because the live price or stock no longer matched the quote.");
  else if (intent.status === "pending_approval") parts.push("Nothing has been ordered yet.");

  const alts = (meta?.alternatives ?? []).map((a) => ({
    productId: a.productId,
    productName: a.productName,
    totalPrice: a.totalPrice,
    deltaEur: a.deltaEur,
    canFulfil: a.canFulfil,
    isSubstitution: a.isSubstitution,
    whyNotChosen: a.note || (!a.canFulfil ? "It cannot deliver the full quantity." : a.deltaEur > 0 ? `It costs ${eur(a.deltaEur)} more.` : "The chosen offer ranked higher overall."),
  }));

  const verification = verifyAuditChain(intent.runId, customerId);

  return {
    intentId: intent.id,
    status: intent.status,
    summary: parts.join(" "),
    timeline,
    decision: {
      by,
      outcome,
      rulesChecked,
      rulesFailed: failing.filter((r) => !overridden.includes(r)),
      rulesOverridden: overridden,
      reasons: intent.policy.reasons,
    },
    offers: {
      consideredCount: meta?.consideredOffers ?? alts.length + 1,
      chosen: line ? { productId: line.productId, productName: line.productName, totalPrice: intent.totalPrice, whyChosen: chosenWhy } : null,
      alternatives: alts,
    },
    facts: intent.basket.map((l) => ({
      productId: l.productId,
      productName: l.productName,
      unitPrice: l.unitPrice,
      totalPrice: l.totalPrice,
      packs: l.packs,
      availableDate: l.availableDate,
      availableQuantity: l.availableQuantity,
      deliveryReliability: l.deliveryReliability,
      signedClaims: l.claimIds.length,
      claimVerification: claimStatus(l),
    })),
    audit: { runId: intent.runId, events: events.length, chainValid: verification.valid },
  };
}
